import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, ts, active
    buy_heap = []  # (-price, ts, id)
    sell_heap = []  # (price, ts, id)
    ts_counter = 0

    def clean_buy():
        while buy_heap:
            negp, ts, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0 or o['side'] != 'buy':
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            p, ts, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0 or o['side'] != 'sell':
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        ts = ts_counter
        ts_counter += 1

        if side == 'buy':
            # match against sells
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sp, sts, sid = sell_heap[0]
                if typ != 'market' and price < sp:
                    break
                sorder = book[sid]
                trade_qty = min(remaining, sorder['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sorder['qty'] -= trade_qty
                if sorder['qty'] <= 0:
                    sorder['active'] = False
                    heapq.heappop(sell_heap)
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, bts, bid = buy_heap[0]
                bp = -negp
                if typ != 'market' and price > bp:
                    break
                border = book[bid]
                trade_qty = min(remaining, border['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                border['qty'] -= trade_qty
                if border['qty'] <= 0:
                    border['active'] = False
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'ts': ts, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, ts, oid))
            else:
                heapq.heappush(sell_heap, (price, ts, oid))
        elif typ == 'limit' and remaining == 0:
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'ts': ts, 'active': False}
        # ioc/market remainder discarded, no book entry needed (or mark inactive)

    return trades

